import "github.com/auth0/go-auth0"

api, err := auth0.New(
    context.Background(),
    "YOUR_AUTH0_DOMAIN",
    auth0.WithStaticToken("YOUR_MANAGEMENT_API_TOKEN"),
)
if err != nil {
    log.Fatal(err)
}

api, err := auth0.NewWithClientCredentials(
    context.Background(),
    "YOUR_AUTH0_DOMAIN",
    "YOUR_CLIENT_ID",
    "YOUR_CLIENT_SECRET",
)
if err != nil {
    log.Fatal(err)
}

import "github.com/auth0/go-auth0/authentication"

auth, err := authentication.New(
    context.Background(),
    "YOUR_AUTH0_DOMAIN",
    authentication.WithClientID("YOUR_CLIENT_ID"),
    authentication.WithClientSecret("YOUR_CLIENT_SECRET"),
)
if err != nil {
    log.Fatal(err)
}

tokenSet, err := auth.OAuth.LoginWithAuthCode(ctx,
    oauth.LoginWithAuthCodeRequest{
        Code:        r.URL.Query().Get("code"),
        RedirectURI: "https://example.com/callback",
    },
)
if err != nil {
    http.Error(w, err.Error(), http.StatusInternalServerError)
    return
}

logoutURL := auth.Logout(authentication.LogoutParams{
    ReturnTo: "https://example.com",
    ClientID: "YOUR_CLIENT_ID",
})
http.Redirect(w, r, logoutURL, http.StatusTemporaryRedirect)

api, err := auth0.NewWithClientCredentials(
    context.Background(),
    "YOUR_AUTH0_DOMAIN",
    "YOUR_CLIENT_ID",
    "YOUR_CLIENT_SECRET",
)
if err != nil {
    log.Fatal(err)
}

user := &management.User{
    Connection: auth0.String("Username-Password-Authentication"),
    Email:      auth0.String("jane@example.com"),
    Password:   auth0.String("securepassword123"),
    Name:       auth0.String("Jane Doe"),
}

if err := api.User.Create(ctx, user); err != nil {
    log.Fatal(err)
}

user, err := api.User.Read(ctx, "auth0|64b2e5f8a3c1d90012ef4567")
if err != nil {
    log.Fatal(err)
}
fmt.Println(*user.Name)

err := api.User.Update(ctx,
    "auth0|64b2e5f8a3c1d90012ef4567",
    &management.User{
        Name: auth0.String("Jane Smith"),
    },
)
if err != nil {
    log.Fatal(err)
}

if err := api.User.Delete(ctx, "auth0|64b2e5f8a3c1d90012ef4567"); err != nil {
    log.Fatal(err)
}
